    public Object callRequest(HttpServletRequest req,@PathVariable String id){Map<String,Object>a=secured(req);ObjectId oid=oid(id);Document o=oid==null?null:svc.c("orders").find(Filters.eq("_id",oid)).first();need(o!=null&&svc.canAccessOrder(a,o),HttpStatus.NOT_FOUND,"Order not found.");Document sender=svc.c("users").find(Filters.eq("_id",userId(a))).first();Document sh=svc.c("shops").find(Filters.eq("_id",o.getObjectId("shopId"))).first();Set<ObjectId> rec=new LinkedHashSet<>();if(o.getObjectId("userId")!=null)rec.add(o.getObjectId("userId"));if(sh!=null&&sh.getObjectId("ownerId")!=null)rec.add(sh.getObjectId("ownerId"));if(o.getObjectId("acceptedRiderId")!=null)rec.add(o.getObjectId("acceptedRiderId"));rec.remove(userId(a));Map<String,Object> payload=Map.of("orderId",id,"orderNumber",o.get("orderNumber"),"fromName",sender==null?"User":s(sender.get("name")),"fromRole",a.get("role"),"createdAt",now());for(ObjectId uid:rec){realtime.user(uid.toHexString(),"notification:call",payload);svc.notifyUser(uid,"CALL_REQUEST","Call request · Order #"+o.getString("orderNumber"),payload.get("fromName")+" ("+payload.get("fromRole")+") requested a call.",Map.of("orderId",id));}return Map.of("success",true,"data",payload);}

    @GetMapping("/api/weather")
    public ResponseEntity<Object> weather(HttpServletRequest req,@RequestParam(defaultValue="23.8103") double lat,@RequestParam(defaultValue="90.4125") double lng){secured(req);try{String url="https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lng+"&current=temperature_2m,weather_code&timezone=auto";HttpResponse<String> r=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(url)).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>299)throw new Exception();var tm=Pattern.compile("\\\"temperature_2m\\\"\\s*:\\s*([-0-9.]+)").matcher(r.body());var cm=Pattern.compile("\\\"weather_code\\\"\\s*:\\s*([0-9]+)").matcher(r.body());double temp=tm.find()?Double.parseDouble(tm.group(1)):0;int code=cm.find()?Integer.parseInt(cm.group(1)):0;Map<String,String> desc=code==0?Map.of("en","clear sky","bn","আকাশ পরিষ্কার"):code<=3?Map.of("en","partly cloudy","bn","আংশিক মেঘলা"):code>=61&&code<=82?Map.of("en","rainy","bn","বৃষ্টি হচ্ছে"):Map.of("en","mixed weather","bn","মিশ্র আবহাওয়া");return ok(Map.of("success",true,"temperature",temp,"weatherCode",code,"description",desc));}catch(Exception e){return out(HttpStatus.BAD_GATEWAY,Map.of("success",false,"message","Weather is temporarily unavailable."));}}

