    public Object dbCollections(){List<Map<String,Object>> rows=new ArrayList<>();svc.mongo.getDb().listCollectionNames().forEach(n->{List<Document> sample=svc.c(n).find().limit(3).into(new ArrayList<>());rows.add(Map.of("name",n,"count",svc.c(n).countDocuments(),"sample",json(sample)));});return Map.of("success",true,"database",svc.dbName,"collections",rows);}
    @GetMapping("/api/db/collection/{name}") public Object dbCollection(@PathVariable String name){need(name.matches("[A-Za-z0-9_-]+"),HttpStatus.BAD_REQUEST,"Invalid collection name");List<Document> docs=svc.c(name).find().limit(50).into(new ArrayList<>());return json(Map.of("success",true,"collection",name,"count",docs.size(),"data",docs));}
    @PostMapping("/api/db/query") public Object dbQuery(@RequestBody Map<String,Object> body){String collection=s(body.get("collection"));need(collection.matches("[A-Za-z0-9_-]+"),HttpStatus.BAD_REQUEST,"Invalid collection name");Document q=body.get("findQuery") instanceof Map<?,?> m?new Document((Map<String,Object>)m):new Document();List<Document> docs=svc.c(collection).find(q).limit(20).into(new ArrayList<>());return json(Map.of("success",true,"count",docs.size(),"data",docs));}
